    public static function public(\Throwable $error): string
    {
        $code = $error->getMessage();
        if ($code === 'O2_SEQUENCE_MISSING') { return 'SEQUENCE_NOT_FOUND'; }
        return in_array($code,self::KNOWN,true)?$code:'O5_ONBOARDING_REFUSED';
    }
